func recordChecksum(id, parent string, worldJSON []byte) string {
	h := sha256.New()
	h.Write([]byte(id))
	h.Write([]byte{0})
	h.Write([]byte(parent))
	h.Write([]byte{0})
	h.Write(worldJSON)
	return "sha256:" + hex.EncodeToString(h.Sum(nil))
}

